import sys

def min_paint(n, m, k, colors, paint):
    def backtrack(index, current_groups, current_paint):
        if index == n:
            if current_groups == k:
                return current_paint
            else:
                return float('inf')

        if colors[index] != 0:
            return backtrack(index + 1, current_groups, current_paint)

        min_cost = float('inf')
        for color in range(1, m + 1):
            new_groups = current_groups
            if index == 0 or colors[index - 1] != color:
                new_groups += 1
            elif index > 0 and colors[index - 1] == color:
                new_groups = current_groups

            cost = backtrack(index + 1, new_groups, current_paint + paint[index][color - 1])
            min_cost = min(min_cost, cost)

        return min_cost

    result = backtrack(0, 0, 0)
    return result if result != float('inf') else -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    colors = list(map(int, data[3:3+n]))

    paint = []
    index = 3 + n
    for _ in range(n):
        row = list(map(int, data[index:index+m]))
        paint.append(row)
        index += m

    result = min_paint(n, m, k, colors, paint)
    print(result)

